/* Durable publications CMS; Quill owns document editing and history. */
const Pub={data:null,loading:false,error:'',q:'',tab:'all',page:1,limit:10,filters:{},filterOpen:false,draft:null,dirty:false,saving:false,errorSave:'',saved:'',session:0,node:null,quill:null,quillSession:0,range:{index:0,length:0},autosave:null,seq:0,controller:null,menu:null,uploads:[],editorLoading:false,clientSection:'news'};
let postList=[];
const postCategories={news:'Новости',links:'Полезные ссылки',instructions:'Инструкции',faq:'Частые вопросы'};
const pubStatuses={draft:'Черновик',published:'Опубликовано',scheduled:'Запланировано',archived:'Архив',deleted:'Удалено'};
function pubEsc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function pubIcon(n){const p={plus:'<path d="M12 5v14M5 12h14"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',filter:'<path d="M3 4h18l-7 8v7l-4 2v-9z"/>',file:'<path d="M14 3H5v18h14V8zM14 3v5h5M8 12h8M8 16h6"/>',image:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="1"/><path d="m4 18 5-5 3 3 4-7 5 8"/>',video:'<rect x="3" y="5" width="13" height="14" rx="3"/><path d="m16 9 5-3v12l-5-3"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/>',dots:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',send:'<path d="m3 10 18-7-7 18-4-7zM10 14 21 3"/>',back:'<path d="m15 5-7 7 7 7"/>',next:'<path d="m9 5 7 7-7 7"/>',emoji:'<circle cx="12" cy="12" r="9"/><path d="M8 14s1 3 4 3 4-3 4-3M8 8h.01M16 8h.01"/>',undo:'<path d="M3 10h10a7 7 0 0 1 0 14M3 10l5-5M3 10l5 5"/>',redo:'<path d="M21 10H11a7 7 0 0 0 0 14M21 10l-5-5M21 10l-5 5"/>',trash:'<path d="M4 6h16M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7M14 10v7"/>',pin:'<path d="m8 3 8 0-1 7 3 3H6l3-3zM12 13v8"/>',gallery:'<rect x="5" y="3" width="16" height="16" rx="3"/><path d="M3 7v14h14M9 13l3-3 5 5"/>',check:'<path d="m5 12 4 4 10-10"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${p[n]||p.file}</svg>`}
function pubDate(v,time=false){return v?new Intl.DateTimeFormat('ru-RU',{timeZone:'Europe/Moscow',...(time?{hour:'2-digit',minute:'2-digit'}:{day:'2-digit',month:'2-digit',year:'numeric'})}).format(new Date(v)):'—'}
async function postAPI(path,options={}){const r=await fetch('/api/web/'+path,options);let x;try{x=await r.json()}catch{throw Error('Сервер вернул некорректный ответ. Повторите позже.')}if(!r.ok)throw Error(typeof x.detail==='string'?x.detail:'Проверьте введённые данные');return x}
function pubQuery(){return new URLSearchParams({q:Pub.q,status:Pub.tab,page:Pub.page,limit:Pub.limit,...Pub.filters})}
function pubRender(){const input=document.activeElement?.matches('[data-pub-search]'),position=document.activeElement?.selectionStart;render();if(input){const x=document.querySelector('[data-pub-search]');x?.focus({preventScroll:true});x?.setSelectionRange(position,position)}}
async function loadPosts(admin=false){if(!admin){postList=await postAPI('posts?category='+Pub.clientSection);render();if(typeof PublicationAlerts!=='undefined')PublicationAlerts.refreshPush();return}if(Pub.helpMode)Pub.filters.section='help';const seq=++Pub.seq;Pub.controller?.abort();Pub.controller=new AbortController();Pub.loading=true;Pub.error='';pubRender();try{const d=await postAPI('admin/publications?'+pubQuery(),{signal:Pub.controller.signal});if(seq===Pub.seq){Pub.data=d;Pub.page=d.page;if(Pub.helpMode){const legacy=await postAPI('admin/help/legacy');if(seq===Pub.seq)Pub.helpLegacy=legacy.items}}}catch(e){if(e.name!=='AbortError'&&seq===Pub.seq)Pub.error=e.message}finally{if(seq===Pub.seq){Pub.loading=false;if(state.view==='admin-posts')pubRender()}}}
function pubBadge(status){return `<span class="pub-badge status-${status}"><i></i>${pubStatuses[status]||status}</span>`}
function pubSection(section){return `<span class="pub-section section-${section}">${postCategories[section]}</span>`}
function pubList(){const d=Pub.data;return `<section class="pub-list-card">${Pub.error?`<div class="pub-error" role="alert">${pubEsc(Pub.error)}<button class="fo-button" data-pub-retry>Повторить</button></div>`:''}${!d?'<div class="pub-skeleton"><span></span><span></span><span></span></div>':d.items.length?`<table class="pub-table"><thead><tr><th>Публикация</th><th>Раздел</th><th>Статус</th><th title="Уникальные просмотры">Открытия</th><th>Дата</th><th></th></tr></thead><tbody>${d.items.map(p=>`<tr data-pub-row="${p.id}" tabindex="0" aria-label="${pubEsc(p.title||'Без заголовка')}"><td class="pub-title-cell"><span class="pub-thumbnail">${p.thumbnail?`<img src="${pubEsc(p.thumbnail)}" alt="" loading="lazy">`:pubIcon('file')}</span><span><strong>${pubEsc(p.title||'Без заголовка')}${p.pinned?pubIcon('pin'):''}</strong><small>${pubEsc(p.excerpt||'Нет текста')}</small></span></td><td class="pub-section-cell">${pubSection(p.section)}</td><td class="pub-status-cell">${pubBadge(p.status)}<small class="pub-notification-state">${p.notify?'Уведомления созданы':p.notify_clients?'Уведомить при публикации':'Без уведомления'}</small></td><td class="pub-view-cell" title="Уникальные клиенты, открывшие публикацию">${pubIcon('eye')} ${new Intl.NumberFormat('ru-RU').format(p.views)}</td><td class="pub-date-cell">${pubDate(p.date)}<small>${pubDate(p.date,true)}</small></td><td class="pub-menu-cell"><button class="fo-button fo-icon-button" data-pub-menu="${p.id}" aria-label="Действия с публикацией">${pubIcon('dots')}</button></td></tr>`).join('')}</tbody></table>`:`<div class="pub-empty">${pubIcon('file')}<h2>Публикаций пока нет</h2><p>${Pub.q||Object.keys(Pub.filters).length?'Измените поиск или фильтры.':'Создайте первую публикацию для клиентов.'}</p><button data-pub-new>${Pub.helpMode?'Добавить материал':'Создать публикацию'}</button></div>`}<footer class="pub-pagination"><span>${d?.total?`Показано ${(Pub.page-1)*Pub.limit+1}–${Math.min(Pub.page*Pub.limit,d.total)} из ${d.total}`:'Нет записей'}</span><div><button data-pub-page="${Pub.page-1}" ${Pub.page<=1?'disabled':''} aria-label="Назад">${pubIcon('back')}</button><span>${Pub.page} / ${Math.max(1,Math.ceil((d?.total||0)/Pub.limit))}</span><button data-pub-page="${Pub.page+1}" ${!d||Pub.page*Pub.limit>=d.total?'disabled':''} aria-label="Далее">${pubIcon('next')}</button></div><span class="pub-limit-control"><select data-pub-limit aria-label="Записей на странице">${[10,25,50].map(n=>`<option ${Pub.limit===n?'selected':''}>${n}</option>`).join('')}</select></span></footer></section>`}
function pubFilter(){if(!Pub.filterOpen)return '';const f=Pub.filters,sel=(key,label,choices)=>`<label>${label}<select name="${key}"><option value="all">Все</option>${choices.map(([v,t])=>`<option value="${v}" ${f[key]===v?'selected':''}>${t}</option>`).join('')}</select></label>`;return `<div class="pub-veil" data-pub-filter-close></div><section class="pub-filter" role="dialog" aria-modal="true" aria-label="Фильтры"><header><h2>Фильтры</h2><button data-pub-filter-close aria-label="Закрыть">${pubIcon('close')}</button></header><form data-pub-filters>${sel('section','Раздел',[['news','Новости'],['links','Полезные ссылки'],['faq','Частые вопросы'],['instructions','Инструкции']])}${sel('status','Статус',Object.entries(pubStatuses))}${sel('media','Медиа',[['none','Без медиа'],['images','Изображения'],['slideshow','Слайд-шоу'],['video','Видео']])}${sel('notification','Уведомления',[['yes','Уведомления созданы'],['no','Без уведомления']])}${sel('pinned','Закрепление',[['yes','Закреплённые'],['no','Обычные']])}${sel('period','Дата',[['day','Сегодня'],['week','Неделя'],['month','Месяц'],['custom','Произвольный период']])}<label>С<input type="date" name="start" value="${pubEsc(f.start)}"></label><label>По<input type="date" name="end" value="${pubEsc(f.end)}"></label><footer><button type="button" data-pub-filter-reset>Сбросить</button><button type="submit" class="fo-button fo-button--primary pub-primary">Применить</button></footer></form></section>`}
function postsPage(admin=false){if(!admin)return `<section class="posts-page client-publications">${pageHeader(postCategories[Pub.clientSection],'Материалы Freeman ONE')}${typeof PublicationAlerts!=='undefined'?PublicationAlerts.settings():''}<div class="pub-client-tabs">${Object.entries(postCategories).filter(([v])=>['news','links'].includes(v)).map(([v,t])=>`<button data-pub-client-section="${v}" aria-pressed="${Pub.clientSection===v}">${t}</button>`).join('')}</div><div class="posts-list">${postList.map(p=>`<button class="post-list-row" data-post-open="${p.id}"><span>${pubEsc(p.title)}<small>${pubEsc(p.excerpt)}</small></span>${pubIcon('next')}</button>`).join('')||'<p>Публикаций пока нет.</p>'}</div></section>`;const tabs=[['all','Все'],['published','Опубликованные'],['draft','Черновики'],['scheduled','Запланировано'],['archived','Архив'],['deleted','Удалённые']],count=Object.values(Pub.filters).filter(x=>x&&x!=='all').length;return `${FreemanComponents.adminScreen({title:Pub.helpMode?'Помощь клиентам':'Публикации',description:Pub.helpMode?'Вопросы и инструкции':'Материалы и уведомления',headingClass:'pub-heading',classes:`publications-page ${Pub.draft?'has-editor':''}`,busy:Pub.loading,actions:`<button class="fo-button fo-button--primary pub-primary" data-pub-new>${pubIcon('plus')}${Pub.helpMode?'Новый материал':'Создать публикацию'}</button>`,nav:`<div class="pub-tabs">${tabs.map(([v,t])=>`<button class="fo-button fo-button--plain" data-pub-tab="${v}" aria-pressed="${Pub.tab===v}">${t}${Pub.data?`<small>${Pub.data.counts[v]||0}</small>`:''}</button>`).join('')}</div>`,tools:`<div class="pub-commandbar"><label class="pub-search">${pubIcon('search')}<input data-pub-search type="search" maxlength="200" value="${pubEsc(Pub.q)}" placeholder="Поиск по заголовку, тексту, разделу..." aria-label="Поиск публикаций"><kbd>Ctrl K</kbd></label><button class="fo-button pub-secondary" data-pub-filter>${pubIcon('filter')} Фильтр${count?' · '+count:''}</button></div>`,content:`${Pub.helpMode?helpLegacyMarkup():''}<div class="pub-workspace">${pubList()}${Pub.draft?'<div data-pub-editor-slot></div>':''}</div>${Pub.editorLoading?'<p class="pub-error">Загружаем публикацию…</p>':''}`,after:'<p class="pub-metric-note">Просмотры — уникальные клиенты. Открытия редактора и предпросмотра не учитываются.</p>'})}` }
function pubMediaHTML(){return `<div class="pub-upload-progress">${Pub.uploads.map(x=>`<small>${pubEsc(x.name)} · ${x.error?pubEsc(x.error):x.progress+'%'}</small>`).join('')}</div><div class="pub-media-list">${(Pub.draft?.media||[]).map((m,i)=>`<div class="pub-media-item" draggable="true" data-pub-drag="${i}"><span class="pub-media-thumb">${m.kind==='image'?`<img src="/api/web/posts/media/${m.name}?thumb=true" alt="">`:pubIcon('video')}</span><div><span>${m.cover_only?'Обложка':m.inline?'В тексте':m.kind==='video'?'Видео':'Изображение'} ${i+1}</span><input data-pub-alt="${i}" aria-label="Описание изображения ${i+1}" placeholder="Описание изображения" value="${pubEsc(m.alt)}"><input data-pub-caption="${i}" aria-label="Подпись ${i+1}" placeholder="Подпись" value="${pubEsc(m.caption)}"></div><button type="button" data-pub-move="${i}" data-direction="-1" ${i===0?'disabled':''} aria-label="Раньше">↑</button><button type="button" data-pub-move="${i}" data-direction="1" ${i===Pub.draft.media.length-1?'disabled':''} aria-label="Позже">↓</button><button type="button" data-pub-remove="${i}" aria-label="Удалить медиа">${pubIcon('trash')}</button></div>`).join('')}</div>`}
function pubEditorHTML(){const p=Pub.draft;const toggle=(key,title,sub,checked)=>`<label class="pub-toggle"><input type="checkbox" name="${key}" ${checked?'checked':''}><i></i><span>${title}<small>${sub}</small></span></label>`;const schedule=p.scheduled_at?new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Moscow',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(p.scheduled_at)).replace(' ','T'):'';return `<section class="pub-editor" role="dialog" aria-modal="true" data-pub-editor-session="${Pub.session}" aria-label="${Pub.helpMode?'Редактор помощи':'Редактор публикации'}"><header><h2>${Pub.helpMode?'Материал помощи':p.id?'Редактирование публикации':'Новая публикация'}</h2><button data-pub-close aria-label="Закрыть редактор">${pubIcon('close')}</button></header><form data-pub-form><div class="pub-editor-fields"><label>Заголовок<input name="title" maxlength="160" value="${pubEsc(p.title)}" placeholder="Введите заголовок публикации..." aria-label="Заголовок"></label><fieldset class="pub-destinations"><legend>Раздел</legend>${(Pub.helpMode?[['faq','Ответы на частые вопросы клиентов'],['instructions','Настройка и пошаговые руководства']]:[['news','Важные обновления, события и новости'],['links','Полезные материалы'],['faq','Ответы для раздела поддержки'],['instructions','Пошаговые руководства для поддержки']]).map(([v,d])=>`<label><input type="radio" name="section" value="${v}" ${p.section===v?'checked':''}><span>${pubIcon(v==='news'?'file':'image')}<span><strong>${postCategories[v]}</strong><small>${d}</small></span><b>${pubIcon('check')}</b></span></label>`).join('')}</fieldset><div><label>Обложка</label><div class="pub-cover-tools"><button type="button" data-pub-upload="cover">${pubIcon('image')}<span>Загрузить изображение<small>JPG, PNG, WebP · до 20 МБ</small></span></button><div data-pub-cover></div></div></div><div class="pub-rich-wrap"><label>Содержание</label><div class="pub-rich-toolbar"><select class="ql-header" aria-label="Стиль текста"><option selected>Обычный текст</option><option value="1">Заголовок 1</option><option value="2">Заголовок 2</option><option value="3">Заголовок 3</option></select><button type="button" class="ql-bold" aria-label="Полужирный"></button><button type="button" class="ql-italic" aria-label="Курсив"></button><button type="button" class="ql-underline" aria-label="Подчёркнутый"></button><button type="button" class="ql-strike" aria-label="Зачёркнутый"></button><button type="button" class="ql-list" value="bullet" aria-label="Список"></button><button type="button" class="ql-list" value="ordered" aria-label="Нумерованный список"></button><button type="button" class="ql-link" aria-label="Вставить ссылку"></button><button type="button" class="ql-image" aria-label="Изображение в текст"></button><button type="button" data-pub-emoji aria-label="Эмодзи">${pubIcon('emoji')}</button><button type="button" class="ql-blockquote" aria-label="Цитата"></button><button type="button" class="ql-code-block" aria-label="Блок кода"></button><select class="ql-color" aria-label="Цвет текста"><option selected></option>${['#667085','#0a84ff','#16864b','#a96c13','#d64141'].map(c=>`<option value="${c}"></option>`).join('')}</select><button type="button" data-pub-undo aria-label="Отменить">${pubIcon('undo')}</button><button type="button" data-pub-redo aria-label="Повторить">${pubIcon('redo')}</button></div><div class="pub-quill"></div><div class="pub-counter">0 слов</div></div><div class="pub-media-section"><label>Медиа</label><div class="pub-media-actions"><button type="button" data-pub-upload="gallery">${pubIcon('image')} Изображения</button><button type="button" data-pub-upload="video">${pubIcon('video')} Видео</button><button type="button" data-pub-slideshow>${pubIcon('gallery')} ${p.slideshow?'Отключить слайд-шоу':'Создать слайд-шоу'}</button></div><div data-pub-media></div></div><div class="pub-settings"><label>Настройки</label>${['faq','instructions'].includes(p.section)?'<input type="checkbox" name="notify_clients" hidden disabled><p class="pub-delivery-note">Справочные материалы публикуются без рассылки клиентам.</p>':toggle('notify_clients','Отправить уведомление клиентам','На сайте со звуком; Telegram — связанным аккаунтам. Повторное редактирование не рассылает заново.',p.notify_clients)}${toggle('pinned','Закрепить публикацию','Показывать в начале раздела',p.pinned)}${toggle('scheduled','Установить дату публикации','Автоматически опубликовать позже · МСК',!!p.scheduled_at)}<label class="pub-schedule" ${p.scheduled_at?'':'hidden'}>Дата и время · МСК<input type="datetime-local" name="scheduled_at" value="${schedule}"></label></div><div class="pub-editor-errors" role="alert"></div><div class="pub-save-state" aria-live="polite"></div>${p.push_delivery?`<small class="pub-delivery-note">Push: принято сервисом ${p.push_delivery.sent||0} · в очереди ${(p.push_delivery.pending||0)+(p.push_delivery.sending||0)} · ошибок ${p.push_delivery.failed||0}. Звук и показ зависят от настроек устройства.</small>`:''}${p.delivery?`<small class="pub-delivery-note">Telegram: доставлено ${p.delivery.sent||0} · в очереди ${(p.delivery.pending||0)+(p.delivery.sending||0)} · ошибок ${p.delivery.failed||0}${p.delivery.failed?'<button type="button" data-pub-retry-notification>Повторить ошибки</button>':''}</small>`:''}<button type="button" class="fo-button pub-preview-button" data-pub-preview>${pubIcon('eye')} Предпросмотр</button></div><footer><button type="submit" class="fo-button" data-pub-save>${p.status==='published'?'Сохранить изменения':'Сохранить черновик'}</button><button type="button" class="fo-button fo-button--primary pub-primary" data-pub-publish>${pubIcon('send')}<span>${p.status==='published'?'Сохранить':p.scheduled_at?'Запланировать':'Опубликовать'}</span></button></footer></form><input type="file" class="pub-file-input" accept="image/jpeg,image/png,image/webp" multiple hidden></section>`}
function pubCapture(){const f=Pub.node?.querySelector('[data-pub-form]');if(!f||!Pub.draft)return;Pub.draft.title=f.elements.title.value;Pub.draft.section=f.elements.section.value;Pub.draft.pinned=f.elements.pinned.checked;Pub.draft.notify_clients=!['faq','instructions'].includes(Pub.draft.section)&&f.elements.notify_clients.checked;Pub.draft.scheduled_at=f.elements.scheduled.checked&&f.elements.scheduled_at.value?f.elements.scheduled_at.value+':00+03:00':null;if(Pub.quill)Pub.draft.content=Pub.quill.getContents();for(const x of Pub.node.querySelectorAll('[data-pub-alt]'))if(Pub.draft.media[Number(x.dataset.pubAlt)])Pub.draft.media[Number(x.dataset.pubAlt)].alt=x.value;for(const x of Pub.node.querySelectorAll('[data-pub-caption]'))if(Pub.draft.media[Number(x.dataset.pubCaption)])Pub.draft.media[Number(x.dataset.pubCaption)].caption=x.value}
function pubBeforeRender(){if(Pub.node){const a=document.activeElement;Pub.focus=Pub.node.contains(a)?{element:a,selector:a.matches('[data-pub-alt]')?'[data-pub-alt="'+a.dataset.pubAlt+'"]':a.matches('[data-pub-caption]')?'[data-pub-caption="'+a.dataset.pubCaption+'"]':null,start:a.selectionStart,end:a.selectionEnd,range:Pub.quill?.getSelection()}:null;pubCapture();Pub.node.remove()}}
function pubMount(){document.body.classList.remove('pub-editor-open');document.querySelector('.pub-portal')?.remove();if(state.view!=='admin-posts')return;const root=document.querySelector('#overlay-root'),page=document.querySelector('.screen[data-screen="admin-posts"] .publications-page');if(!root||!page)return;if(Pub.draft){if(!Pub.node||Number(Pub.node.dataset.pubEditorSession)!==Pub.session){Pub.node=null;Pub.quill=null;const t=document.createElement('div');t.innerHTML=pubEditorHTML();Pub.node=t.firstElementChild}const portal=document.createElement('div');portal.className='publications-page pub-portal';portal.innerHTML='<div class="pub-editor-veil" data-pub-close></div>';portal.append(Pub.node);root.append(portal);document.body.classList.add('pub-editor-open');pubInitQuill();pubUpdateEditor();if(Pub.node.dataset.mounted)Pub.node.style.animation="none";Pub.node.dataset.mounted="true";if(Pub.focus&&!state.modal){const f=Pub.focus;if(!f.element.isConnected&&f.selector)f.element=Pub.node.querySelector(f.selector)||f.element;if(f.element.isConnected){f.element.focus({preventScroll:true});if(f.start!=null)f.element.setSelectionRange(f.start,f.end);if(f.range)Pub.quill.setSelection(f.range,"silent")}Pub.focus=null}}if(Pub.filterOpen){const portal=document.createElement('div');portal.className='publications-page pub-portal pub-filter-portal';portal.innerHTML=pubFilter();root.append(portal);FreemanUI.controls(portal);if(innerWidth>767)FreemanUI.anchorPanel(portal.querySelector('.pub-filter'),page.querySelector('[data-pub-filter]'));}if(Pub.menu)pubMountMenu()}
function pubInitQuill(){if(Pub.quill)return;const q=new Quill(Pub.node.querySelector('.pub-quill'),{theme:'snow',placeholder:'Напишите текст публикации...',formats:['header','bold','italic','underline','strike','list','blockquote','code-block','link','image','color','button'],modules:{toolbar:{container:Pub.node.querySelector('.pub-rich-toolbar'),handlers:{image(){pubChooseFile('inline')},link(){pubLinkDialog()}}},history:{delay:1000,maxStack:100,userOnly:true}}});Pub.quill=q;q.setContents(Pub.draft.content||{ops:[{insert:'\n'}]},'silent');q.history.clear();q.on('selection-change',range=>{if(range)Pub.range=range});q.on('text-change',()=>{pubCapture();pubChanged();pubUpdateCounter()});pubUpdateCounter();q.root.addEventListener('paste',e=>{if([...e.clipboardData?.files||[]].length){e.preventDefault();pubUpload([...e.clipboardData.files],'inline')}});Pub.node.querySelector('.pub-file-input').addEventListener('change',e=>{pubUpload([...e.target.files],e.target.dataset.purpose||'gallery');e.target.value=''});FreemanUI.controls(Pub.node)}
function pubUpdateCounter(){const text=Pub.quill?.getText().trim()||'';if(Pub.node)Pub.node.querySelector('.pub-counter').textContent=(text?text.split(/\s+/u).length:0)+' слов · '+text.length+' / 50 000'}
function pubUpdateEditor(){if(!Pub.node)return;Pub.node.querySelector('[data-pub-media]').innerHTML=pubMediaHTML();const cover=Pub.draft.cover;Pub.node.querySelector('[data-pub-cover]').innerHTML=cover?`<img src="/api/web/posts/media/${cover}?thumb=true" alt="Обложка"><button type="button" data-pub-cover-remove aria-label="Убрать обложку">${pubIcon('close')}</button>`:'';Pub.node.querySelector('.pub-editor-errors').textContent=Pub.errorSave;Pub.node.querySelector('.pub-save-state').textContent=Pub.saving?'Сохраняется…':Pub.dirty?'Есть изменения':Pub.saved?'Сохранено · '+Pub.saved:'';Pub.node.querySelectorAll('[data-pub-save],[data-pub-publish]').forEach(b=>b.disabled=Pub.saving||Pub.publishing||Pub.uploads.some(x=>!x.error&&x.progress<100));const s=Pub.node.querySelector('[data-pub-publish] span');if(s)s.textContent=Pub.saving?'Сохраняем…':Pub.draft.status==='published'?'Сохранить':Pub.draft.scheduled_at?'Запланировать':'Опубликовать';Pub.node.querySelector('[data-pub-slideshow]').innerHTML=pubIcon('gallery')+(Pub.draft.slideshow?' Отключить слайд-шоу':' Создать слайд-шоу')}
function pubChanged(){Pub.dirty=true;Pub.errorSave='';clearTimeout(Pub.autosave);pubUpdateEditorStatus();if(Pub.draft.status!=='published')Pub.autosave=setTimeout(()=>pubSave(true).catch(()=>{}),1500)}
function pubUpdateEditorStatus(){if(!Pub.node)return;Pub.node.querySelectorAll('[data-pub-save],[data-pub-publish]').forEach(b=>b.disabled=!!(Pub.saving||Pub.publishing||Pub.uploads.some(x=>!x.error&&x.progress<100)));Pub.node.querySelector('.pub-save-state').textContent=Pub.saving?'Сохраняется…':Pub.dirty?'Есть изменения':Pub.saved?'Сохранено · '+Pub.saved:'';Pub.node.querySelector('.pub-editor-errors').textContent=Pub.errorSave}
async function pubSave(auto=false){if(Pub.saving)throw Error('Дождитесь сохранения');if(Pub.uploads.some(x=>!x.error&&x.progress<100))throw Error('Дождитесь загрузки медиа');pubCapture();if(auto&&!Pub.draft.title.trim()&&!Pub.quill?.getText().trim()&&!Pub.draft.media.length)return;clearTimeout(Pub.autosave);const revision=JSON.stringify(Pub.draft.content)+JSON.stringify(Pub.draft.media)+Pub.draft.title+Pub.draft.section+Pub.draft.pinned+Pub.draft.notify_clients+Pub.draft.scheduled_at;const payload=JSON.parse(JSON.stringify(Pub.draft));Pub.saving=true;Pub.errorSave='';pubUpdateEditorStatus();try{const d=await postAPI('admin/publications'+(Pub.draft.id?'/'+Pub.draft.id:''),{method:Pub.draft.id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});pubCapture();const current=JSON.stringify(Pub.draft.content)+JSON.stringify(Pub.draft.media)+Pub.draft.title+Pub.draft.section+Pub.draft.pinned+Pub.draft.notify_clients+Pub.draft.scheduled_at;if(current===revision){Pub.draft=d;Pub.dirty=false}else{Pub.draft.id=d.id;Pub.draft.version=d.version;Pub.dirty=true;clearTimeout(Pub.autosave);Pub.autosave=setTimeout(()=>pubSave(true).catch(()=>{}),1500)}Pub.saved=pubDate(new Date().toISOString(),true);if(!auto)say(payload.status==='published'?'Изменения сохранены':'Черновик сохранён');loadPosts(true).catch(()=>{});return d}catch(e){Pub.errorSave=e.message;throw e}finally{Pub.saving=false;pubUpdateEditorStatus()}}
async function pubCanLeave(){if(Pub.saving||Pub.publishing||Pub.uploads.some(x=>!x.error&&x.progress<100)){say('Дождитесь сохранения и загрузки медиа');return false}if(!Pub.draft||!Pub.dirty)return true;try{if(Pub.draft.status!=='published'&&!Pub.saving){await pubSave(true);return !Pub.dirty}}catch{}return await pubConfirm('Есть несохранённые изменения','Закрыть без сохранения? Текст можно сохранить, оставшись в редакторе.','Закрыть без сохранения')}
async function pubClose(){if(Pub.saving){say('Дождитесь сохранения');return}if(!(await pubCanLeave()))return;clearTimeout(Pub.autosave);Pub.draft=null;Pub.node=null;Pub.quill=null;Pub.dirty=false;render()}
async function pubNew(data){if(Pub.saving||Pub.publishing){say('Дождитесь сохранения');return}if(Pub.draft&&!(await pubCanLeave()))return;if(window.FreemanCabinetBoot){try{await FreemanCabinetBoot.loadEditor();pubRegisterButton()}catch(error){say(error.message);return}}clearTimeout(Pub.autosave);Pub.session++;Pub.node=null;Pub.quill=null;Pub.dirty=false;Pub.errorSave='';Pub.saved='';Pub.uploads=[];Pub.draft=data||{title:'',section:Pub.helpMode?'faq':'news',status:'draft',content:{ops:[{insert:'\n'}]},media:[],cover:'',slideshow:false,pinned:false,notify_clients:!Pub.helpMode,scheduled_at:null};render();Pub.node?.querySelector('[name=title]')?.focus({preventScroll:true})}
async function pubEdit(id){Pub.editorLoading=true;pubRender();try{const d=await postAPI('posts/'+id);if(['deleted','archived'].includes(d.status)){say('Сначала восстановите публикацию в черновики');return}await pubNew(d)}catch(e){say(e.message)}finally{Pub.editorLoading=false;if(state.view==='admin-posts')pubRender()}}
function pubConfirm(title,text,label='Подтвердить'){return new Promise(resolve=>{const old=state.modal;state.modal=`<div class="modal-backdrop pub-confirm-backdrop"><section class="pub-confirm publications-page" role="dialog" aria-modal="true" aria-label="${pubEsc(title)}"><h2>${pubEsc(title)}</h2><p>${pubEsc(text)}</p><div><button data-pub-confirm-no>Отмена</button><button class="pub-danger" data-pub-confirm-yes>${pubEsc(label)}</button></div></section></div>`;render();const key=e=>{if(e.key==="Escape"){e.preventDefault();cleanup(false)}if(e.key==="Tab"){e.preventDefault();const buttons=[...document.querySelectorAll(".pub-confirm button")];buttons[(buttons.indexOf(document.activeElement)+(e.shiftKey?-1:1)+buttons.length)%buttons.length]?.focus()}};const cleanup=value=>{document.removeEventListener("keydown",key,true);state.modal=old;render();resolve(value)};document.addEventListener("keydown",key,true);document.querySelector('[data-pub-confirm-no]').onclick=()=>cleanup(false);document.querySelector('[data-pub-confirm-yes]').onclick=()=>cleanup(true);document.querySelector('[data-pub-confirm-no]').focus()})}
async function pubAction(id,action){if(Pub.saving||Pub.publishing)return;if(Pub.draft?.id===Number(id)&&Pub.dirty&&!(await pubCanLeave()))return;clearTimeout(Pub.autosave);const row=Pub.draft?.id===Number(id)?Pub.draft:Pub.data?.items.find(p=>p.id===Number(id));if(!row)return;if(['delete','purge','archive'].includes(action)&&!await pubConfirm(action==='purge'?'Удалить навсегда?':action==='archive'?'Переместить в архив?':'Удалить публикацию?',action==='purge'?'Действие нельзя отменить.':'Клиенты больше не увидят публикацию. Вы сможете восстановить её в черновики.',action==='archive'?'В архив':action==='purge'?'Удалить навсегда':'Удалить'))return;const d=await postAPI('admin/publications/'+id+'/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,version:row.version})});Pub.menu=null;if(action==='duplicate')await pubNew(d);else if(Pub.draft?.id===Number(id)){if(['delete','purge','archive','restore'].includes(action)){Pub.draft=null;Pub.node=null;Pub.quill=null;Pub.dirty=false}else Pub.draft=d}say({delete:'Публикация удалена',purge:'Публикация удалена навсегда',archive:'Публикация перемещена в архив',restore:'Восстановлена в черновики',retry_notification:'Ошибки доставки поставлены в очередь'}[action]||'Готово');await loadPosts(true)}
function pubMountMenu(){const p=Pub.data?.items.find(x=>x.id===Number(Pub.menu));if(!p)return;const actions=p.status==='deleted'?[['restore','Восстановить'],['purge','Удалить навсегда']]:p.status==='archived'?[['restore','Восстановить'],['duplicate','Дублировать'],['delete','Удалить']]:[['edit','Редактировать'],['preview','Предпросмотр'],['duplicate','Дублировать'],...(['published','scheduled'].includes(p.status)?[['archive','Архивировать']]:[]),['delete','Удалить']];const root=document.querySelector('#overlay-root'),el=document.createElement('div');el.className='publications-page fo-scope pub-portal';const button=document.querySelector(`[data-pub-menu="${Pub.menu}"]`),rect=button?.getBoundingClientRect();el.innerHTML=`<div class="pub-menu-veil" data-pub-menu-close></div><div class="pub-row-menu" role="menu" style="right:${Math.max(12,innerWidth-(rect?.right||innerWidth-12))}px;top:${Math.min(innerHeight-280,(rect?.bottom||180)+4)}px">${actions.map(([a,t])=>`<button role="menuitem" data-pub-action="${a}" data-id="${p.id}" class="${['delete','purge'].includes(a)?'pub-danger-text':''}">${t}</button>`).join('')}</div>`;root.append(el);FreemanUI.controls(el);FreemanUI.anchorPanel(el.querySelector('.pub-row-menu'),button)}
function pubChooseFile(purpose){pubCapture();const f=Pub.node.querySelector('.pub-file-input');f.accept=purpose==='video'?'video/mp4,video/webm,video/quicktime':'image/jpeg,image/png,image/webp';f.multiple=purpose!=='cover';f.dataset.purpose=purpose;f.click()}
async function pubUpload(files,purpose){const session=Pub.session;pubCapture();if(files.length+Pub.draft.media.length>10){Pub.errorSave='До 10 файлов в публикации';pubUpdateEditorStatus();return}for(const file of files){const item={name:file.name,progress:0,error:''};Pub.uploads.push(item);pubUpdateEditor();try{if(file.size>20*1024*1024)throw Error('Файл больше 20 МБ');const data=await new Promise((resolve,reject)=>{const f=new FileReader();f.onload=()=>resolve(String(f.result).split(',')[1]);f.onerror=reject;f.readAsDataURL(file)});const result=await new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('POST','/api/web/admin/posts/media');xhr.setRequestHeader('Content-Type','application/json');xhr.upload.onprogress=e=>{item.progress=Math.min(99,Math.round(e.loaded/e.total*100));pubUpdateEditor()};xhr.onload=()=>{let d;try{d=JSON.parse(xhr.responseText)}catch{reject(Error('Ошибка загрузки'));return}xhr.status>=200&&xhr.status<300?resolve(d):reject(Error(d.detail||'Ошибка загрузки'))};xhr.onerror=()=>reject(Error('Соединение прервано'));xhr.send(JSON.stringify({name:file.name,mime:file.type,data}))});if(Pub.session!==session)return;Pub.draft.media.push({name:result.name,kind:result.kind,alt:'',caption:'',inline:purpose==='inline',cover_only:purpose==='cover'});if(purpose==='cover')Pub.draft.cover=result.name;if(purpose==='inline'){Pub.quill.insertEmbed(Pub.range?.index||0,'image',result.url,'user');Pub.quill.setSelection((Pub.range?.index||0)+1)}item.progress=100;pubChanged()}catch(e){item.error=e.message;Pub.errorSave=e.message}finally{pubUpdateEditor()}}}
function pubLinkDialog(){pubCapture();const range=Pub.quill.getSelection()||Pub.range;const current=range?Pub.quill.getText(range.index,range.length):'';state.modal=`<div class="modal-backdrop pub-confirm-backdrop"><section class="pub-confirm publications-page"><h2>Вставить ссылку</h2><form data-pub-link-form><label>HTTPS-ссылка<input name="url" type="url" placeholder="https://" required></label><label>Текст ссылки<input name="text" value="${pubEsc(current)}"></label><div><button type="button" data-pub-link-cancel>Отмена</button><button class="fo-button fo-button--primary pub-primary" type="submit">Вставить</button></div></form></section></div>`;render();document.querySelector('[data-pub-link-form]').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),url=f.get('url');try{const u=new URL(url);if(u.protocol!=='https:'||!u.hostname||u.username||u.password)throw Error();state.modal=null;render();const text=f.get('text')||url;Pub.quill.deleteText(range.index,range.length,'user');Pub.quill.insertText(range.index,text,{link:url},'user');Pub.quill.setSelection(range.index+text.length)}catch{say('Используйте HTTPS-ссылку')}};document.querySelector('[data-pub-link-cancel]').onclick=()=>{state.modal=null;render()};document.querySelector('[name=url]').focus()}
function postMedia(p){const media=(p.media||[]).filter(m=>!m.inline&&!m.cover_only);if(!media.length)return '';return `<div class="post-gallery ${p.slideshow?'is-slideshow':''}"><div class="post-gallery-track">${media.map(m=>`<figure>${m.kind==='video'?`<video controls playsinline preload="metadata" src="/api/web/posts/media/${m.name}"></video>`:`<img src="/api/web/posts/media/${m.name}" alt="${pubEsc(m.alt)}" loading="lazy">`}${m.caption?`<figcaption>${pubEsc(m.caption)}</figcaption>`:''}</figure>`).join('')}</div>${p.slideshow&&media.length>1?`<div class="post-gallery-controls"><button data-pub-slide="-1" aria-label="Предыдущее изображение">${pubIcon('back')}</button><span>${media.map((m,i)=>`<button data-pub-slide-to="${i}" aria-label="Изображение ${i+1}" aria-pressed="${i===0}"></button>`).join('')}</span><button data-pub-slide="1" aria-label="Следующее изображение">${pubIcon('next')}</button></div>`:''}</div>`}
function postArticle(p){return `<article class="post-article"><small>${postCategories[p.section||p.category]}${p.published_at?' · '+pubDate(p.published_at):''}</small><h2>${pubEsc(p.title)}</h2>${p.cover?`<img class="post-cover" src="/api/web/posts/media/${p.cover}" alt="${pubEsc(p.media?.find(m=>m.name===p.cover)?.alt)}">`:''}<div class="post-rich">${p.body||''}</div>${postMedia(p)}</article>`}
async function openPost(id){const p=await postAPI('posts/'+id);state.modal=`<div class="modal-backdrop pub-preview-backdrop"><section class="post-reader publications-page"><button data-close-modal aria-label="Закрыть">${pubIcon('close')}</button>${postArticle(p)}</section></div>`;try{const saved=JSON.parse(localStorage.getItem(noticeReadKey())||'[]');for(const n of accountNotifications(state.data))if(notificationTarget(n)?.kind==='post'&&Number(notificationTarget(n).value)===Number(id)&&!saved.includes(noticeId(n)))saved.push(noticeId(n));localStorage.setItem(noticeReadKey(),JSON.stringify(saved))}catch{}render();pubSetupGalleries();if(!state.data.profile.is_admin)postAPI('posts/'+id+'/view',{method:'POST'}).catch(()=>{});}
function pubSetupGalleries(){for(const el of document.querySelectorAll('.post-gallery.is-slideshow')){const track=el.querySelector('.post-gallery-track');track.addEventListener('scroll',()=>{const i=Math.round(track.scrollLeft/track.clientWidth);el.querySelectorAll('[data-pub-slide-to]').forEach((b,j)=>b.setAttribute('aria-pressed',String(i===j)))},{passive:true})}}
async function pubPreview(){pubCapture();const session=Pub.session;const preview=await postAPI('admin/publications/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Pub.draft)});if(Pub.session!==session)return;state.modal=`<div class="modal-backdrop pub-preview-backdrop"><section class="post-reader publications-page"><button data-close-modal aria-label="Закрыть предпросмотр">${pubIcon('close')}</button>${postArticle({...Pub.draft,...preview})}</section></div>`;render();pubSetupGalleries()}
function pubEmoji(){const existing=Pub.node.querySelector('.pub-emoji');if(existing){existing.remove();return}const picker=document.createElement('div');picker.className='pub-emoji';picker.setAttribute('role','dialog');picker.setAttribute('aria-label','Выбрать эмодзи');picker.innerHTML=['😀','😊','👍','❤️','🎉','✅','🔑','📱','💻','🌐','🚀','📣','⚠️','💡','📚','✨','🔒','💳','📅','🛠️','🔥','👋','🙏','💬'].map(x=>`<button type="button" data-pub-emoji-insert="${x}" aria-label="${x}">${x}</button>`).join('');Pub.node.querySelector('.pub-rich-wrap').append(picker)}
document.addEventListener('input',e=>{if(e.target.matches('[data-pub-search]')){Pub.q=e.target.value;Pub.page=1;clearTimeout(Pub.searchTimer);Pub.controller?.abort();Pub.seq++;Pub.searchTimer=setTimeout(()=>loadPosts(true),300)}else if(e.target.closest('[data-pub-form]')&&!e.target.closest('.ql-editor')){pubCapture();pubChanged()}});
document.addEventListener('change',e=>{if(e.target.matches('[data-pub-limit]')){Pub.limit=Number(e.target.value);Pub.page=1;loadPosts(true)}else if(e.target.closest('[data-pub-form]')){pubCapture();if(e.target.name==='scheduled')Pub.node.querySelector('.pub-schedule').hidden=!e.target.checked;pubChanged()}});
document.addEventListener('submit',async e=>{if(e.target.matches('[data-pub-form]')){e.preventDefault();try{await pubSave()}catch(err){Pub.errorSave=err.message;pubUpdateEditorStatus()}}if(e.target.matches('[data-pub-filters]')){e.preventDefault();const f=Object.fromEntries([...new FormData(e.target)].filter(([k,v])=>v&&v!=='all'));if(f.period==='custom'&&(!f.start||!f.end||f.start>f.end)){say('Проверьте начало и конец периода');return}Pub.filters=f;Pub.tab='all';Pub.page=1;Pub.filterOpen=false;loadPosts(true)}});
document.addEventListener('click',async e=>{const t=e.target.closest('[data-pub-new],[data-pub-row],[data-pub-menu],[data-pub-menu-close],[data-pub-action],[data-pub-close],[data-pub-tab],[data-pub-filter],[data-pub-filter-close],[data-pub-filter-reset],[data-pub-page],[data-pub-retry],[data-pub-upload],[data-pub-remove],[data-pub-move],[data-pub-cover-remove],[data-pub-slideshow],[data-pub-preview],[data-pub-publish],[data-pub-emoji],[data-pub-emoji-insert],[data-pub-undo],[data-pub-redo],[data-post-open],[data-pub-client-section],[data-pub-retry-notification],[data-pub-slide],[data-pub-slide-to]');if(!t)return;try{if(t.hasAttribute('data-pub-new'))return pubNew();if(t.dataset.postOpen)return await openPost(t.dataset.postOpen);if(t.dataset.pubClientSection){Pub.clientSection=t.dataset.pubClientSection;return loadPosts(false)}if(t.hasAttribute('data-pub-filter')){Pub.filterOpen=!Pub.filterOpen;render();return}if(t.hasAttribute('data-pub-filter-close')){Pub.filterOpen=false;render();return}if(t.hasAttribute('data-pub-filter-reset')){Pub.filters={};Pub.tab='all';Pub.page=1;Pub.filterOpen=false;return loadPosts(true)}if(t.dataset.pubTab){Pub.tab=t.dataset.pubTab;delete Pub.filters.status;Pub.page=1;return loadPosts(true)}if(t.dataset.pubPage){Pub.page=Number(t.dataset.pubPage);return loadPosts(true)}if(t.hasAttribute('data-pub-retry'))return loadPosts(true);if(t.hasAttribute('data-pub-close'))return pubClose();if(t.dataset.pubMenu){Pub.menu=Number(t.dataset.pubMenu);render();return}if(t.hasAttribute('data-pub-menu-close')){Pub.menu=null;render();return}if(t.dataset.pubAction){Pub.menu=null;render();if(t.dataset.pubAction==='edit')return pubEdit(t.dataset.id);if(t.dataset.pubAction==='preview')return openPost(t.dataset.id);return pubAction(t.dataset.id,t.dataset.pubAction)}if(t.dataset.pubRow)return pubEdit(t.dataset.pubRow);if(t.dataset.pubUpload)return pubChooseFile(t.dataset.pubUpload);if(t.hasAttribute('data-pub-preview'))return pubPreview();if(t.hasAttribute('data-pub-publish')){if(Pub.publishing||Pub.saving)return;Pub.publishing=true;Pub.quill?.enable(false);pubUpdateEditorStatus();try{await pubSave(false);if(Pub.draft.status==='published'&&!Pub.draft.scheduled_at){say('Изменения сохранены');return}const d=await postAPI('admin/publications/'+Pub.draft.id+'/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'publish',version:Pub.draft.version})});Pub.draft=d;Pub.dirty=false;Pub.node=null;Pub.quill=null;Pub.session++;say(d.status==='scheduled'?'Публикация запланирована':'Публикация опубликована');return loadPosts(true)}finally{Pub.publishing=false;Pub.quill?.enable(true);pubUpdateEditorStatus()}}if(t.hasAttribute('data-pub-retry-notification'))return pubAction(Pub.draft.id,'retry_notification');if(t.hasAttribute('data-pub-slideshow')){const n=Pub.draft.media.filter(m=>m.kind==='image'&&!m.inline&&!m.cover_only).length;if(!Pub.draft.slideshow&&n<2){say('Загрузите минимум два изображения в медиа');return}Pub.draft.slideshow=!Pub.draft.slideshow;pubChanged();pubUpdateEditor();return}if(t.hasAttribute('data-pub-cover-remove')){Pub.draft.cover='';pubChanged();pubUpdateEditor();return}if(t.dataset.pubRemove!==undefined){const i=Number(t.dataset.pubRemove),m=Pub.draft.media[i];if(m.inline){const ops=Pub.quill.getContents().ops.filter(op=>op.insert?.image!=='/api/web/posts/media/'+m.name);Pub.quill.setContents({ops},'user')}Pub.draft.media.splice(i,1);if(Pub.draft.cover===m.name)Pub.draft.cover='';if(Pub.draft.media.filter(m=>m.kind==='image'&&!m.inline&&!m.cover_only).length<2)Pub.draft.slideshow=false;pubChanged();pubUpdateEditor();return}if(t.dataset.pubMove!==undefined){const i=Number(t.dataset.pubMove),j=i+Number(t.dataset.direction);if(j>=0&&j<Pub.draft.media.length)[Pub.draft.media[i],Pub.draft.media[j]]=[Pub.draft.media[j],Pub.draft.media[i]];pubChanged();pubUpdateEditor();return}if(t.hasAttribute('data-pub-undo'))return Pub.quill.history.undo();if(t.hasAttribute('data-pub-redo'))return Pub.quill.history.redo();if(t.hasAttribute('data-pub-emoji'))return pubEmoji();if(t.dataset.pubEmojiInsert){const r=Pub.range;Pub.quill.insertText(r.index,t.dataset.pubEmojiInsert,'user');Pub.quill.setSelection(r.index+t.dataset.pubEmojiInsert.length);Pub.node.querySelector('.pub-emoji')?.remove();return}if(t.dataset.pubSlide!==undefined||t.dataset.pubSlideTo!==undefined){const track=t.closest('.post-gallery').querySelector('.post-gallery-track'),index=t.dataset.pubSlideTo!==undefined?Number(t.dataset.pubSlideTo):Math.round(track.scrollLeft/track.clientWidth)+Number(t.dataset.pubSlide);track.scrollTo({left:index*track.clientWidth,behavior:'smooth'})}}catch(err){Pub.errorSave=err.message;pubUpdateEditorStatus();say(err.message)}});
let pubDrag=-1;document.addEventListener('dragstart',e=>{const t=e.target.closest('[data-pub-drag]');if(t){pubCapture();pubDrag=Number(t.dataset.pubDrag)}});document.addEventListener('dragover',e=>{if(e.target.closest('[data-pub-drag]'))e.preventDefault()});document.addEventListener('drop',e=>{const t=e.target.closest('[data-pub-drag]');if(!t||pubDrag<0)return;e.preventDefault();const target=Number(t.dataset.pubDrag);Pub.draft.media.splice(target,0,Pub.draft.media.splice(pubDrag,1)[0]);pubDrag=-1;pubChanged();pubUpdateEditor()});
window.addEventListener('beforeunload',e=>{if(Pub.dirty){e.preventDefault();e.returnValue=''}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('[data-post-open]')&&e.target.tagName!=='BUTTON'){e.preventDefault();openPost(e.target.dataset.postOpen).catch(x=>say(x.message))}if(typeof state==='undefined'||state.view!=='admin-posts')return;if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();e.stopImmediatePropagation();document.querySelector('[data-pub-search]')?.focus()}if(e.key==='Enter'&&e.target.matches('[data-pub-row]'))pubEdit(e.target.dataset.pubRow);if(e.key==='Escape'&&!state.modal){if(Pub.filterOpen){Pub.filterOpen=false;render()}else if(Pub.menu){Pub.menu=null;render()}else if(Pub.draft)pubClose()}},true);
let postNoticeBusy=false;async function refreshPostNotices(){if(postNoticeBusy||!state.data||isPreview()||document.hidden)return;postNoticeBusy=true;try{await NoticeCenter.load();const posts=await postAPI('posts?limit=50');const notices=posts.filter(p=>p.notify).map(p=>({id:p.id,title:p.title,text:p.plain.slice(0,500),category:postCategories[p.section],created_at:p.published_at||p.created_at,target:p.url,notify:true})),legacy=(state.data.news||[]).filter(n=>!/[?&]post=/.test(n.target||''));state.data.news=[...posts.filter(p=>p.section==='news').map(p=>({id:p.id,title:p.title,text:p.excerpt,category:'Новости',created_at:p.published_at||p.created_at,target:p.url,notify:p.notify})),...legacy].slice(0,50);state.extra.publicationNotices=notices;await PublicationAlerts.receive(notices);NoticeCenter.badge()}catch{}finally{postNoticeBusy=false}}
/* One publication alert controller; no automatic browser permission prompts. */
const PublicationAlerts=(()=>{
 let timer,started=false,lastPush=0,pushEnabled=false;
 const uid=()=>state.data?.profile?.freeman_id||'';
 const key=()=>NoticeCenter.soundKey();
 const soundOn=()=>NoticeCenter.soundOn();
 function settings({open=false}={}){queueMicrotask(refreshPush);return `<details ${open?'open':''} class="pub-alert-settings fo-notice-settings fo-scope"><summary>${FreemanComponents.icon('bell')||svg('bell')}<span>Уведомления включены</span>${actionIcon('chevron-down')}</summary><div class="fo-notice-preferences"><button class="fo-button fo-button--plain" role="switch" aria-label="Звук уведомлений на сайте" aria-checked="${soundOn()}" data-publication-sound><span class="fo-switch" aria-hidden="true"><b></b></span><span>Звук: ${soundOn()?'включён':'выключен'}</span></button><button class="fo-button fo-button--plain" data-publication-push>${pushEnabled?'Отключить push':'Подключить push'}</button><small>На сайте — автоматически. Push требует разрешения браузера. На iPhone откройте сайт с экрана «Домой». Звук — после касания.</small><p role="status" data-publication-push-message></p></div></details>`}
 function unlock(){if(uid()&&soundOn())prepareSupportSound()}
 async function refreshPush(){if(!uid()||!navigator.serviceWorker?.getRegistration)return;const current=uid();try{const reg=await navigator.serviceWorker.getRegistration('/');const sub=await reg?.pushManager.getSubscription();if(!sub){pushEnabled=false;return}const r=await fetch('/api/web/notifications/push/status',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({endpoint:sub.endpoint})});if(!r.ok)return;const d=await r.json();if(uid()!==current)return;pushEnabled=!!d.enabled;const b=document.querySelector('[data-publication-push]');if(b)b.textContent=pushEnabled?'Отключить push':'Подключить push'}catch{}}
 async function enablePush(button){unlock();button=button||document.querySelector('[data-publication-push]');const message=button?.closest('.pub-alert-settings')?.querySelector('[data-publication-push-message]');if(button)button.disabled=true;
  try{
   if(!('serviceWorker'in navigator)||!('PushManager'in window)||!('Notification'in window))throw Error('На iPhone добавьте сайт на экран «Домой» и откройте его оттуда.');
   if(pushEnabled){const registration=await navigator.serviceWorker.getRegistration('/');const sub=await registration?.pushManager.getSubscription();if(sub){const removed=await fetch('/api/web/notifications/push/subscription',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({endpoint:sub.endpoint})});if(!removed.ok)throw Error('Не удалось отключить push');}pushEnabled=false;if(button)button.textContent='Включить push';if(message)message.textContent='Push отключён для этого аккаунта и браузера.';return}
   const permission=await Notification.requestPermission();if(permission!=='granted')throw Error('Разрешите уведомления в настройках браузера.');
   const r=await fetch('/api/web/notifications/push/config',{cache:'no-store'});if(!r.ok)throw Error('Не удалось подключить push');const cfg=await r.json();if(!cfg.available)throw Error('Сервис push пока не готов. Отчёты доступны в колокольчике.');
   const registration=await navigator.serviceWorker.register('/admin-notifications-sw.js',{scope:'/',updateViaCache:'none'});await navigator.serviceWorker.ready;
   const encoded=cfg.public_key.replace(/-/g,'+').replace(/_/g,'/'),key=Uint8Array.from(atob(encoded+'='.repeat((4-encoded.length%4)%4)),c=>c.charCodeAt(0));
   const existing=await registration.pushManager.getSubscription();const subscription=existing||await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:key});
   const result=await fetch('/api/web/notifications/push/subscription',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(subscription.toJSON())});if(!result.ok){const detail=await result.json().catch(()=>({}));throw Error(typeof detail.detail==='string'?detail.detail:'Не удалось сохранить push-подписку. Повторите подключение.');}pushEnabled=true;if(button)button.textContent='Отключить push';if(message)message.textContent='Push подключён. Новые публикации придут и при закрытом сайте. Звук задаётся в настройках устройства.';
  }catch(e){if(message)message.textContent=e.message}finally{if(button)button.disabled=false}
 }
 async function receive(notices){if(!uid()||state.data.profile.is_admin||document.hidden)return;
  const storage='freeman-publications-seen:'+uid();let seen;try{seen=JSON.parse(localStorage.getItem(storage)||'null')}catch{}
  const ids=notices.map(n=>String(n.id));
  // First visit establishes a baseline; old posts remain in the bell, without a sound flood.
  if(!Array.isArray(seen)){try{localStorage.setItem(storage,JSON.stringify(ids))}catch{}return}
  const fresh=notices.filter(n=>!seen.includes(String(n.id)));if(!fresh.length)return;
  const show=()=>{let latest;try{latest=JSON.parse(localStorage.getItem(storage)||'[]')}catch{latest=seen}
   const n=fresh.find(n=>!latest.includes(String(n.id)));try{localStorage.setItem(storage,JSON.stringify([...new Set([...ids,...latest])].slice(0,300)))}catch{}
   if(!n)return;
   FreemanComponents.showNoticeBanner({
    className:'publication-toast',iconName:'file-text',label:'Новая публикация',title:n.title,text:noticePlain(n.text),
    openAttributes:`data-post-open="${Number(n.id)}"`,dismissAttributes:'data-publication-dismiss'
   });
   if(soundOn()&&Date.now()-lastPush>5000)playSupportSentSound();
  };
  if(navigator.locks)await navigator.locks.request(storage,show);else show();
 }
 document.addEventListener('pointerdown',unlock,{passive:true});document.addEventListener('keydown',unlock,{passive:true});
 document.addEventListener('click',e=>{const button=e.target.closest('[data-publication-push],[data-publication-sound],[data-publication-dismiss],.publication-toast [data-post-open]');if(!button)return;if(button.hasAttribute('data-publication-push')){enablePush(button);return}if(button.hasAttribute('data-publication-sound')){try{localStorage.setItem(key(),soundOn()?'off':'on')}catch{}button.setAttribute('aria-checked',String(soundOn()));button.lastElementChild.textContent='Звук: '+(soundOn()?'включён':'выключен');unlock()}else FreemanComponents.dismissNoticeBanner(document.querySelector('.publication-toast'))});
 function schedule(){clearTimeout(timer);if(started)timer=setTimeout(async()=>{await refreshPostNotices();schedule()},20000)}
 window.addEventListener('pageshow',()=>{started=true;schedule()});window.addEventListener('pagehide',()=>{started=false;clearTimeout(timer)});
 document.addEventListener('visibilitychange',()=>{if(!document.hidden){refreshPostNotices();schedule()}});
 navigator.serviceWorker?.addEventListener('message',e=>{if(e.data?.type==='freeman-publication'){lastPush=Date.now();refreshPostNotices()}});
 started=true;setTimeout(async()=>{await refreshPostNotices();schedule()},1000);
 return{receive,settings,soundOn,refreshPush};
})();

const initialPost=new URLSearchParams(location.search).get('post');if(initialPost&&/^\d+$/.test(initialPost)){const timer=setInterval(()=>{if(state.data&&!isPreview()){clearInterval(timer);openPost(initialPost).catch(e=>say(e.message))}},500)}

pubMount=FreemanUI.enhance(pubMount,()=>Pub.node);
pubMountMenu=FreemanUI.enhance(pubMountMenu,()=>document.querySelector('.pub-portal'));
pubUpdateEditor=FreemanUI.enhance(pubUpdateEditor,()=>Pub.node);

function helpLegacyMarkup(){const rows=Pub.helpLegacy||[];return rows.length?`<section class="fo-help-legacy fo-card"><h2>Текущие вопросы и инструкции</h2><p>Откройте запись, измените её и опубликуйте. Исходный вариант останется доступен клиентам до публикации.</p>${rows.map((x,i)=>`<div class="fo-help-legacy-item"><button type="button" class="fo-row-action" data-help-edit="${i}"><span>${pubEsc(x.title)}<small>${postCategories[x.section]}${x.enabled===false?' · скрыто':''}</small></span>${pubIcon('next')}</button><button type="button" class="fo-button fo-button--compact fo-button--plain" data-help-toggle="${i}">${x.enabled===false?'Показать':'Скрыть'}</button></div>`).join('')}</section>`:''}

async function openHelpLibrary(){if(!state.data?.profile?.is_admin)return;Pub.helpMode=true;Pub.filters={section:'help'};Pub.page=1;Pub.tab='all';Pub.helpLegacy=[];await loadView('admin-posts',{help:true})}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-help-library],[data-help-edit],[data-help-toggle]');if(!b)return;try{if(b.hasAttribute('data-help-library')){state.modal=null;await openHelpLibrary();return}if(b.dataset.helpToggle!==undefined){const item=Pub.helpLegacy?.[Number(b.dataset.helpToggle)];if(!item)return;if(!await FreemanUI.confirm({title:item.enabled===false?'Показать материал?':'Скрыть материал?',message:item.title,accept:item.enabled===false?'Показать':'Скрыть'}))return;await postAPI('admin/help/legacy',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({help_key:item.help_key,enabled:item.enabled===false})});await loadPosts(true);return}const x=Pub.helpLegacy?.[Number(b.dataset.helpEdit)];if(x)await pubNew({title:x.title,section:x.section,help_key:x.help_key,status:'draft',content:{ops:[{insert:x.text+'\n'}]},media:[],cover:'',slideshow:false,pinned:false,notify_clients:false,scheduled_at:null})}catch(error){say(error.message)}});
